// Pre-export validation: re-opens the generated bytes and checks them independently of the writer.
import type { Database, SqlJsStatic } from 'sql.js';
import { readZipTolerant } from '../zip/reader';
import { ANIM_SCHEMA, DATA_SCHEMA, EFFECT_TYPES, LT } from './schema';

export interface Check { category: string; ok: boolean; details: string[]; }
export interface ValidationResult { ok: boolean; checks: Check[]; }

const dec = new TextDecoder();
const UUID = /^[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}$/;
type Json = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

function rows(db: Database, sql: string): unknown[][] {
  const r = db.exec(sql);
  return r.length ? (r[0].values as unknown[][]) : [];
}
const jsonCol = (v: unknown): Json => JSON.parse(dec.decode(v as Uint8Array));

export function validateTsproj(SQL: SqlJsStatic, bytes: Uint8Array): ValidationResult {
  const checks: Check[] = [];
  const add = (category: string, errs: string[], okNote?: string) =>
    checks.push({ category, ok: errs.length === 0, details: errs.length ? errs : okNote ? [okNote] : [] });

  // --- ZIP integrity ---
  const zip = readZipTolerant(bytes);
  const zerr: string[] = [...zip.warnings];
  if (zip.mode !== 'central-ok') zerr.push('central directory not consistent');
  add('ZIP integrity', zerr, `${zip.entries.size} entries, central directory OK, CRC OK`);

  // --- Project structure ---
  const serr: string[] = [];
  const roots = new Set([...zip.entries.keys()].map((k) => k.split('/')[0]));
  if (roots.size !== 1) serr.push(`expected exactly one root folder, found ${roots.size}`);
  const root = [...roots][0] ?? '';
  if (!UUID.test(root)) serr.push(`root folder "${root}" is not an uppercase UUID`);
  const dataBytes = zip.entries.get(`${root}/data`);
  if (!dataBytes) serr.push('missing <root>/data');
  const animNames = [...zip.entries.keys()].filter((k) => k.startsWith(`${root}/Animations/`) && k.endsWith('.tsanim'));
  if (!animNames.length) serr.push('no Animations/*.tsanim');
  for (const k of zip.entries.keys()) if (!/^[^/]+\/(data|Animations\/[^/]+\.tsanim|Textures\/[^/]+|Thumbnails\/[^/]+\.png|Audio\/[^/]+)$/.test(k)) serr.push(`unexpected entry "${k}"`);
  add('Project structure', serr, `root ${root}, ${animNames.length} animation clips`);
  if (!dataBytes) return { ok: false, checks };

  // --- SQLite integrity ---
  const lerr: string[] = [];
  const header = 'SQLite format 3\0';
  const openDb = (name: string, b: Uint8Array, schema: Record<string, string>): Database | null => {
    if (dec.decode(b.subarray(0, 16)) !== header) { lerr.push(`${name}: not a SQLite file`); return null; }
    try {
      const db = new SQL.Database(b);
      const ic = rows(db, 'PRAGMA integrity_check');
      if (ic[0]?.[0] !== 'ok') lerr.push(`${name}: integrity_check failed`);
      const got = new Map(rows(db, "SELECT name,sql FROM sqlite_master WHERE type='table'").map((r) => [r[0] as string, r[1] as string]));
      for (const [t, sql] of Object.entries(schema)) if (got.get(t) !== sql) lerr.push(`${name}: table ${t} schema differs from app-made files`);
      for (const t of got.keys()) if (!(t in schema)) lerr.push(`${name}: unexpected table ${t}`);
      return db;
    } catch (e) { lerr.push(`${name}: ${(e as Error).message}`); return null; }
  };
  const data = openDb('data', dataBytes, DATA_SCHEMA);
  const anims = new Map<string, Database>();
  for (const k of animNames) {
    const id = k.slice(k.lastIndexOf('/') + 1, -'.tsanim'.length);
    const db = openDb(id, zip.entries.get(k)!, ANIM_SCHEMA);
    if (db) anims.set(id, db);
  }
  add('SQLite integrity', lerr, `${1 + anims.size} databases, integrity_check ok, schemas identical to app-made files`);
  if (!data) return { ok: false, checks };

  try {
    // --- Canvas & FPS ---
    const cerr: string[] = [];
    const meta: Json = {};
    for (const r of rows(data, 'SELECT key,value FROM meta_d')) meta[r[0] as string] = jsonCol(r[1]);
    const me = meta.me ?? {};
    const w = me.re?.w, h = me.re?.h, fr = me.fr;
    if (!(Number.isInteger(w) && w > 0 && w <= 16384)) cerr.push(`invalid canvas width ${w}`);
    if (!(Number.isInteger(h) && h > 0 && h <= 16384)) cerr.push(`invalid canvas height ${h}`);
    if (!(typeof fr === 'number' && fr > 0 && fr <= 240)) cerr.push(`invalid fps ${fr}`);
    if (me.id !== root) cerr.push('meta id does not match root folder');
    const clipIds = new Set(rows(data, 'SELECT id FROM res_anim_clips').map((r) => r[0] as string));
    const sceneRows = rows(data, 'SELECT id,"index" FROM scenes');
    const clipData = new Map<string, Json>();
    for (const [id, db] of anims) {
      const r = rows(db, 'SELECT data FROM animationClip');
      if (r.length !== 1) { cerr.push(`${id}: expected 1 animationClip row`); continue; }
      const c = jsonCol(r[0][0]); clipData.set(id, c);
      if (c.id !== id) cerr.push(`${id}: animationClip id mismatch`);
      if (c.re?.w !== w || c.re?.h !== h) cerr.push(`${id}: canvas differs from project`);
      if (c.fr !== fr) cerr.push(`${id}: fps differs from project`);
    }
    add('Canvas & FPS', cerr, `${w}×${h} @ ${fr} fps in project and all ${clipData.size} clips`);

    // --- Layer refs / Drawing refs / Timeline ---
    const lerrs: string[] = [], derrs: string[] = [], terrs: string[] = [], serrs: string[] = [];
    let totalDrawings = 0, totalLayers = 0;
    const edges = new Map<string, string[]>();
    for (const [id, db] of anims) {
      const c = clipData.get(id); if (!c) continue;
      const layers = new Map<string, { type: number; d: Json }>();
      for (const r of rows(db, 'SELECT id,type,data FROM layers')) layers.set(r[0] as string, { type: r[1] as number, d: jsonCol(r[2]) });
      const drawings = new Map<string, Json>();
      for (const r of rows(db, 'SELECT id,data FROM drawings')) drawings.set(r[0] as string, jsonCol(r[1]));
      totalDrawings += drawings.size; totalLayers += layers.size;
      for (const lid of c.lO as string[]) if (!layers.has(lid)) lerrs.push(`${id}: lO references missing layer ${lid}`);
      const lo = (c.lO as string[])[0];
      if (layers.get(lo)?.type !== LT.BACKGROUND) lerrs.push(`${id}: first lO entry is not the Background layer`);
      for (const [lid, l] of layers) {
        if (l.d.Id !== lid) lerrs.push(`${id}: layer ${lid} Id mismatch`);
        if (l.type === LT.TIMELINE) {
          if (!(c.lO as string[]).includes(lid)) lerrs.push(`${id}: timeline layer ${lid} not in lO`);
          // Visibility: app-made files store only Vi:false (hidden); an absent key means visible.
          if ('Vi' in l.d && l.d.Vi !== false) lerrs.push(`${id}: timeline layer ${lid} has visibility Vi=${JSON.stringify(l.d.Vi)} (only false is known)`);
          let prevEnd = 0;
          const spans: [number, number][] = [];
          for (const did of l.d.dr as string[]) {
            const d = drawings.get(did);
            if (!d) { derrs.push(`${id}: layer ${lid} references missing drawing ${did}`); continue; }
            if (d.l !== lid) derrs.push(`${id}: drawing ${did} points to a different layer`);
            if (!(Number.isInteger(d.s) && Number.isInteger(d.e) && d.s >= 1 && d.e >= d.s)) terrs.push(`${id}: drawing ${did} has invalid frame range ${d.s}..${d.e}`);
            spans.push([d.s, d.e]);
          }
          spans.sort((a, b) => a[0] - b[0]);
          for (const [s, e] of spans) { if (s <= prevEnd) terrs.push(`${id}: overlapping drawings in layer ${lid} at frame ${s}`); prevEnd = Math.max(prevEnd, e); }
        } else if (EFFECT_TYPES.has(l.type)) {
          const owner = layers.get(l.d.LI as string);
          if (!owner) lerrs.push(`${id}: effect ${lid} owner layer ${l.d.LI} missing`);
          else if (!((owner.d.Ef as string[] | undefined) ?? []).includes(lid)) lerrs.push(`${id}: owner layer ${l.d.LI} does not list effect ${lid}`);
          if (l.type === LT.EFFECT) for (const k of ['c0', 'c1', 'c2', 'c3']) { const v = l.d[k]; if (!Array.isArray(v) || v.length !== 2 || !v.every((x: number) => Number.isFinite(x))) lerrs.push(`${id}: effect ${lid} has invalid ${k}`); }
        } else if (l.type === LT.VECTOR || l.type === LT.CLIP) {
          for (const ef of (l.d.Ef as string[] | undefined) ?? []) { const e = layers.get(ef); if (!e || !EFFECT_TYPES.has(e.type) || e.d.LI !== lid) lerrs.push(`${id}: layer ${lid} Ef ${ef} does not resolve to its own effect`); }
          const di = l.d.DI as string;
          const d = drawings.get(di);
          if (!d) derrs.push(`${id}: content layer ${lid} references missing drawing ${di}`);
          else if (!(d.ly as string[]).includes(lid)) derrs.push(`${id}: drawing ${di} does not list its content layer ${lid}`);
          if (l.type === LT.CLIP) {
            const target = l.d.cl?.id as string;
            if (!clipIds.has(target) || !anims.has(target)) serrs.push(`${id}: instance ${lid} references missing clip ${target}`);
            else { const a = edges.get(id) ?? []; a.push(target); edges.set(id, a); }
          } else {
            for (const it of l.d.s as Json[]) for (const sp of it.p.s as Json[]) for (const n of sp.p as Json[])
              for (const v of [n.p, n.i, n.o]) if (v && !v.every((x: number) => Number.isFinite(x))) derrs.push(`${id}: non-finite coordinate in ${lid}`);
          }
        }
      }
      for (const [did, d] of drawings) {
        for (const ly of d.ly as string[]) if (!layers.has(ly)) derrs.push(`${id}: drawing ${did} references missing content layer ${ly}`);
        if (!layers.has(d.l)) derrs.push(`${id}: drawing ${did} references missing timeline layer`);
      }
    }
    add('Layer references', lerrs, `${totalLayers} layers consistent`);
    add('Drawing references', derrs, `${totalDrawings} drawings consistent`);
    add('Timeline & frame duration', terrs, 'frame ranges are 1-based, inclusive, non-overlapping per layer');

    // --- Symbol refs ---
    for (const [id] of sceneRows.map((r) => [r[0] as string])) if (!clipIds.has(id)) serrs.push(`scene ${id} is not a registered clip`);
    for (const id of clipIds) if (!anims.has(id)) serrs.push(`clip ${id} registered in data but file missing`);
    for (const id of anims.keys()) if (!clipIds.has(id)) serrs.push(`clip file ${id} not registered in data`);
    const color = new Map<string, number>();
    const dfs = (n: string): boolean => {
      color.set(n, 1);
      for (const m of edges.get(n) ?? []) {
        if (color.get(m) === 1) return true;
        if (!color.get(m) && dfs(m)) return true;
      }
      color.set(n, 2);
      return false;
    };
    for (const n of anims.keys()) if (!color.get(n) && dfs(n)) { serrs.push('cyclic symbol reference'); break; }
    add('Symbol references', serrs, `${clipIds.size} clips, no dangling or cyclic references`);

    // --- Asset integrity ---
    const aerr: string[] = [];
    const texEntries = [...zip.entries.keys()].filter((k) => k.includes('/Textures/') || k.includes('/Audio/'));
    const referenced = rows(data, 'SELECT textureId FROM res_shared_textures').map((r) => r[0] as string);
    for (const t of referenced) if (!zip.entries.has(`${root}/Textures/${t}`)) aerr.push(`missing texture ${t}`);
    if (rows(data, 'SELECT id FROM res_audio_clips').length && !texEntries.length) aerr.push('audio clip registered without files');
    add('Asset integrity', aerr, `${texEntries.length} asset files (V1 writes none)`);
  } finally {
    data.close();
    for (const db of anims.values()) db.close();
  }
  return { ok: checks.every((c) => c.ok), checks };
}
